#!/bin/bash
sed -i '/stockQuantity = it.stockQuantity/a\                    barcode = it.barcode,\n                    category = it.category,\n                    brand = it.brand,\n                    wholesalePrice = it.wholesalePrice,\n                    taxRate = it.taxRate,\n                    imageUri = it.imageUri,\n                    expiryDate = it.expiryDate,\n                    batchNumber = it.batchNumber,\n                    status = it.status' app/src/main/java/com/example/data/drive/GoogleDriveManager.kt

sed -i '/stockQuantity = itemDto.stockQuantity/a\                    barcode = itemDto.barcode,\n                    category = itemDto.category,\n                    brand = itemDto.brand,\n                    wholesalePrice = itemDto.wholesalePrice,\n                    taxRate = itemDto.taxRate,\n                    imageUri = itemDto.imageUri,\n                    expiryDate = itemDto.expiryDate,\n                    batchNumber = itemDto.batchNumber,\n                    status = itemDto.status' app/src/main/java/com/example/data/drive/GoogleDriveManager.kt
